     pub(super) fn init(upool: Upool) -> Result<(), Error> {
         if unlikely(PHYS_MEMORY_MANAGER_INIT.load(ORDER)) {
             return Err(Error::new(
                 ErrorCode::InvalidArgument,
                 "physical memory manager already initialized",
