         // SAFETY: this happens during kernel initialization and no other threads are running.
         unsafe { PHYS_MEMORY_MANAGER.write(PhysMemoryManager { upool }) };
         PHYS_MEMORY_MANAGER_INIT.store(true, ORDER);
